struct value_type { const short first; unsigned int second; };
struct node {
  int color;
  node *parent;
  node *left;
  node *right;
  value_type value;
};
struct tree { node header; unsigned int node_count; };
struct result { node *position; bool inserted; };

extern "C" node *tree_insert(tree *, node *, node *, const value_type &)
  __asm__("_M_insert__t8_Rb_tree5ZsZt4pair2ZCsZUiZt10_Select1st1Zt4pair2ZCsZUiZt4less1ZsZt12my_allocator1ZUiP18_Rb_tree_node_baseT1RCt4pair2ZCsZUi");
result *insert_unique(result *, tree *, const value_type &)
  __asm__("insert_unique__t8_Rb_tree5ZsZt4pair2ZCsZUiZt10_Select1st1Zt4pair2ZCsZUiZt4less1ZsZt12my_allocator1ZUiRCt4pair2ZCsZUi");

result *insert_unique(result *out, tree *self, const value_type &value) {
  node *y = &self->header;
  node *x = self->header.parent;
  bool comp = true;
  while (x != 0) {
    y = x;
    comp = value.first < x->value.first;
    x = comp ? x->left : x->right;
  }
  node *j = y;
  if (comp) {
    if (j == self->header.left) {
      out->position = tree_insert(self, x, y, value);
      out->inserted = true;
      return out;
    }
    if (j->left != 0) {
      j = j->left;
      while (j->right != 0) j = j->right;
    } else {
      node *p = j->parent;
      while (j == p->left) {
        j = p;
        p = p->parent;
      }
      j = p;
    }
  }
  if (j->value.first < value.first) {
    out->position = tree_insert(self, x, y, value);
    out->inserted = true;
  } else {
    out->position = j;
    out->inserted = false;
  }
  return out;
}
